//! The scanner accuracy measurement (D4): the committed photo-realistic corpus
//! in `corpus/scanner/` with its ground-truth quads.
//!
//! The corpus is generated by `scripts/generate-scanner-corpus.py` (real camera
//! photos cannot be committed): paper pages on desks with perspective,
//! rotation, shadow gradients, vignetting, sensor noise, busy backgrounds,
//! soft focus and two-page spreads with a dark spine. Every image has the
//! expected page quads, so the detector's accuracy is a measured number, not a
//! promise.
//!
//! A case passes when the page count matches and the corners are close enough:
//! mean corner error <= 3.5 % of the image diagonal and every corner <= 6 %.
//! The test asserts the roadmap's acceptance target of at least 80 %.

use super::*;
use serde::Deserialize;
use std::path::PathBuf;

#[derive(Debug, Deserialize)]
struct GroundTruth {
    #[allow(dead_code)]
    version: u32,
    images: Vec<GroundTruthImage>,
}

#[derive(Debug, Deserialize)]
struct GroundTruthImage {
    file: String,
    #[allow(dead_code)]
    conditions: Vec<String>,
    pages: Vec<Vec<[f32; 2]>>,
}

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../corpus/scanner")
}

fn load_ground_truth() -> GroundTruth {
    let path = corpus_dir().join("ground-truth.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("the scanner corpus is missing ({}): {error}", path.display()));
    serde_json::from_str(&text).expect("the scanner corpus ground truth is not valid JSON")
}

fn distance(left: Point, right: [f32; 2]) -> f32 {
    ((left[0] - right[0]).powi(2) + (left[1] - right[1]).powi(2)).sqrt()
}

/// Returns (mean error, max error) in pixels for one expected page.
fn corner_error(detected: &[Point; 4], expected: &[[f32; 2]]) -> (f32, f32) {
    let mut total = 0.0;
    let mut worst: f32 = 0.0;
    for (index, corner) in detected.iter().enumerate() {
        let error = distance(*corner, expected[index]);
        total += error;
        worst = worst.max(error);
    }
    (total / detected.len() as f32, worst)
}

#[test]
fn the_corpus_meets_the_acceptance_target() {
    let truth = load_ground_truth();
    assert!(truth.images.len() >= 12, "the corpus must keep its coverage (got {} images)", truth.images.len());
    let mut passed = 0usize;
    let mut report = String::new();
    for image in &truth.images {
        let path = corpus_dir().join(&image.file);
        let decoded = image::open(&path)
            .unwrap_or_else(|error| panic!("cannot read corpus image {}: {error}", path.display()))
            .to_rgba8();
        let (width, height) = decoded.dimensions();
        let diagonal = ((width * width + height * height) as f32).sqrt();
        let detected = detect_pages(&decoded);
        let mut ok = detected.len() == image.pages.len();
        let mut details = String::new();
        if ok {
            for (index, expected) in image.pages.iter().enumerate() {
                let (mean, worst) = corner_error(&detected[index].corners, expected);
                details.push_str(&format!("p{index} mean={:.1}px max={:.1}px; ", mean, worst));
                if mean > diagonal * 0.035 || worst > diagonal * 0.06 {
                    ok = false;
                }
                let _ = expected;
            }
        } else {
            details = format!(
                "expected {} page(s), detected {}; corners={:?}",
                image.pages.len(),
                detected.len(),
                detected.iter().map(|page| page.corners).collect::<Vec<_>>()
            );
        }
        if ok {
            passed += 1;
        }
        report.push_str(&format!("{:<36} {:<4} {}\n", image.file, if ok { "PASS" } else { "FAIL" }, details));
    }
    let total = truth.images.len();
    let accuracy = passed * 100 / total;
    println!("scanner corpus: {passed}/{total} usable ({accuracy} %; target 80 %)\n{report}");
    assert!(
        passed * 100 >= 80 * total,
        "the scanner corpus accuracy fell below the 80 % acceptance target: {passed}/{total}\n{report}"
    );
}

#[test]
fn a_two_page_spread_is_split_and_a_single_page_is_not() {
    let truth = load_ground_truth();
    for image in &truth.images {
        let path = corpus_dir().join(&image.file);
        let decoded = image::open(&path).expect("corpus image").to_rgba8();
        let detected = detect_pages(&decoded);
        assert_eq!(
            detected.len(),
            image.pages.len(),
            "{} should be detected as {} page(s)",
            image.file,
            image.pages.len()
        );
        if image.pages.len() == 2 {
            // The split must put the left page first: its centre is left of the
            // right page's centre.
            let left = detected[0].corners;
            let right = detected[1].corners;
            let left_center = (left[0][0] + left[1][0] + left[2][0] + left[3][0]) / 4.0;
            let right_center = (right[0][0] + right[1][0] + right[2][0] + right[3][0]) / 4.0;
            assert!(left_center < right_center, "{}: the left page must come first", image.file);
        }
    }
}
